void processPayment(Request req) {
  try {
    httpClient.post("/charge", req);
  } catch (TimeoutException e) {
    // Retry immediately on timeout
    httpClient.post("/charge", req);
  }
}

public void processPayment(String orderId) {
    if (paymentRepo.exists(orderId)) {
        return; // Already processed
    }
    paymentRepo.save(new Payment(orderId));
    chargeUser(orderId);
}
